from decimal import Decimal, ROUND_HALF_UP
import re


def format_size(count):
    """A byte count as text with a binary unit. See TASK.md."""
    if isinstance(count, bool) or not isinstance(count, int):
        raise TypeError("count must be an int")

    negative = count < 0
    count = abs(count)

    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    unit_values = [1, 1024, 1024**2, 1024**3, 1024**4]

    if count < 1024:
        result = f"{count} B"
    else:
        unit_index = 0
        for i in range(len(units) - 1, 0, -1):
            if count >= unit_values[i]:
                unit_index = i
                break

        value = Decimal(count) / Decimal(unit_values[unit_index])
        rounded = value.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

        if rounded >= 1024 and unit_index < len(units) - 1:
            unit_index += 1
            rounded = Decimal('1.0')

        result = f"{rounded} {units[unit_index]}"

    if negative:
        result = "-" + result

    return result


def parse_size(text):
    """The byte count that a size text stands for. See TASK.md."""
    text = text.strip()

    pattern = r'^(-?)(\d+)(?:\.(\d+))?\s*(B|KiB|MiB|GiB|TiB)$'
    match = re.match(pattern, text)

    if not match:
        raise ValueError(f"Invalid size format: {text}")

    sign, integer_part, fraction_part, unit = match.groups()

    if unit == 'B' and fraction_part is not None:
        raise ValueError("B unit cannot have a fraction")

    units = {'B': 1, 'KiB': 1024, 'MiB': 1024**2, 'GiB': 1024**3, 'TiB': 1024**4}
    unit_value = units[unit]

    if fraction_part:
        number = Decimal(integer_part) + Decimal(f"0.{fraction_part}")
    else:
        number = Decimal(integer_part)

    total_bytes = number * Decimal(unit_value)

    if total_bytes % 1 != 0:
        raise ValueError(f"Result is not a whole number of bytes")

    result = int(total_bytes)
    if sign == '-':
        result = -result

    return result
